import{_ as i,l,o as e,c as n,v as t,p as s,x as o,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"远程证明","description":"","frontmatter":{"title":"远程证明","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/remote-attestation.md","filePath":"cs/remote-attestation.md","lastUpdated":1789023840000}'),c={name:"cs/remote-attestation.md"};function E(_,a,m,u,A,f){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="远程证明" tabindex="-1">远程证明 <a class="header-anchor" href="#远程证明" aria-label="Permalink to &quot;远程证明&quot;">​</a></h1><div class="epigraph"><p>远程证明让验证者得到一份由硬件根签名的度量：启动了什么、飞地测量是什么。信任锚在厂商证书链，策略在验证者：度量不匹配就不交秘密。</p><footer>—— 据 Coker et al. 对证明架构；Intel SGX 远程证明文档；TPM PC Client 规范点名</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/confidential-computing">机密计算</a>要先证明再交钥。缺口是<strong>报价协议</strong>：谁签、签什么、如何吊销。不写伪造证明的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>本地 TEE 只能自己信。远程：引用（quote）含测量与随机挑战。缺口是验证者策略与厂商基础设施可用性。</p><h3 id="吊销" tabindex="-1">吊销 <a class="header-anchor" href="#吊销" aria-label="Permalink to &quot;吊销&quot;">​</a></h3><p>CPU 微码漏洞后证明密钥可能被吊销。可用性与安全再次打架。</p><p><span class="marginnote">TPM/SGX 证明文献。禁止伪造。安全启动下一课是本地链。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：挑战、度量、签名、验证者比对预期哈希。下一课安全启动链：本地从 ROM 到内核。</p>',12)),(e(),s(h,null,{default:o(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E9%AA%8C%E8%AF%81%E8%80%85%E6%8C%91%E6%88%98%22%5D%20--%3E%20Q%5B%22%E7%A1%AC%E4%BB%B6%E7%AD%BE%E5%90%8D%E7%9A%84%E5%BA%A6%E9%87%8F%22%5D%0A%20%20Q%20--%3E%20POL%5B%22%E4%B8%8E%E9%A2%84%E6%9C%9F%E6%B5%8B%E9%87%8F%E6%AF%94%E5%AF%B9%22%5D%0A%20%20POL%20--%3E%20REL%5B%22%E9%87%8A%E6%94%BE%E5%AF%86%E9%92%A5%E6%88%96%E6%8B%92%E7%BB%9D%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把「我是谁」从软件自述换成硬件根。安全启动是同一度量在启动路径上的本地版本。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写伪造报价。安全启动链下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>机密计算靠证明才交钥。</li><li>报价 = 度量 + 挑战 + 硬件签。</li><li>验证者策略与厂商链是 TCB。</li><li>下一课安全启动链。</li><li>出处：Coker et al.；Intel SGX 证明；TPM 规范。</li></ul>',8))])}const T=i(c,[["render",E]]);export{P as __pageData,T as default};
